//! Gate G10's engine rows (D-351, §1.12.28) and the timed cancel rows (A12.11). By hand, release, `#[ignore]`:
//!
//! ```text
//! HIKASA_GATE_DIR=/var/tmp/hikasa-work/<dir>/gates cargo test -p hikasa-hex --release --test gates -- \
//!     --ignored --nocapture --test-threads 1
//! ```
//!
//! Inputs are generated by a seeded xorshift into `HIKASA_GATE_DIR` (default: the system temp folder), once, and
//! reused by the rows: a 4 GiB pair (the right one with 1,000 differing runs of 1–64 bytes) and a copy of its left
//! file, a 1 GiB and a 256 MiB pair with 1,000 edits (insertions, deletions, replacements of 1–4,096 bytes). Delete
//! the folder after the run. Each row prints its figures; the thresholds are asserted.
// A counting allocator cannot be written without `unsafe` (`GlobalAlloc` is an unsafe trait); as in the other
// memory tests of the workspace, this test binary opts out explicitly and every occurrence carries a SAFETY note.
#![allow(unsafe_code)]

mod common;

use std::alloc::{GlobalAlloc, Layout, System};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicIsize, Ordering};
use std::time::{Duration, Instant};

use common::{Edit, XorShift, lspec};
use hikasa_core::{CancelToken, Ctl};
use hikasa_hex::{
    AlignMode, HexAlignOptions, HexDocument, HexFinder, HexLayout, HexLoadOptions, HexPattern,
    HexView, align,
};
use hikasa_vfs::{FollowLinks, LocalVfs, StreamOptions, Vfs, VfsSource, compare_sources};

struct Counting;

static LIVE: AtomicIsize = AtomicIsize::new(0);
static PEAK: AtomicIsize = AtomicIsize::new(0);

fn grew(by: isize) {
    let now = LIVE.fetch_add(by, Ordering::Relaxed) + by;
    PEAK.fetch_max(now, Ordering::Relaxed);
}

// SAFETY: every method forwards to `System`, which upholds the `GlobalAlloc` contract; the counters are static
// atomics, so counting never allocates or re-enters.
unsafe impl GlobalAlloc for Counting {
    // SAFETY: the caller's guarantees for `layout` are passed on to `System::alloc` unchanged.
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        grew(layout.size() as isize);
        // SAFETY: forwarded with the caller's guarantees.
        unsafe { System.alloc(layout) }
    }
    // SAFETY: `ptr` and `layout` come from `alloc`/`realloc` above, as `System::dealloc` requires.
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size() as isize, Ordering::Relaxed);
        // SAFETY: forwarded with the caller's guarantees.
        unsafe { System.dealloc(ptr, layout) }
    }
    // SAFETY: the caller's guarantees for `ptr`, `layout` and `new_size` are passed on unchanged.
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
        grew(new_size as isize - layout.size() as isize);
        // SAFETY: forwarded with the caller's guarantees.
        unsafe { System.realloc(ptr, layout, new_size) }
    }
}

#[global_allocator]
static GLOBAL: Counting = Counting;

const MIB: u64 = 1 << 20;
const GIB: u64 = 1 << 30;

fn gate_dir() -> PathBuf {
    let dir = std::env::var_os("HIKASA_GATE_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir)
        .join("hikasa-hex-gates");
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

/// The session's visitor configuration: the default mmap policy, 4 threads.
fn stream() -> StreamOptions {
    StreamOptions {
        threads: 4,
        ..StreamOptions::default()
    }
}

/// Writes `len` seeded bytes to `path` in 64 MiB pieces, `patch` applied to each piece (offset, bytes).
fn generate(path: &Path, len: u64, seed: u64, patch: &dyn Fn(u64, &mut [u8])) {
    if std::fs::metadata(path).is_ok_and(|m| m.len() == len) {
        return;
    }
    let mut f = std::io::BufWriter::new(std::fs::File::create(path).unwrap());
    let mut rng = XorShift(seed);
    let mut at = 0;
    while at < len {
        let n = (64 * MIB).min(len - at) as usize;
        let mut piece = rng.bytes(n);
        patch(at, &mut piece);
        f.write_all(&piece).unwrap();
        at += n as u64;
    }
    f.flush().unwrap();
}

/// The 4 GiB pair and the copy of its left file.
fn big_pair() -> (PathBuf, PathBuf, PathBuf) {
    let dir = gate_dir();
    let (l, r, c) = (
        dir.join("4g-left"),
        dir.join("4g-right"),
        dir.join("4g-copy"),
    );
    let len = 4 * GIB;
    let mut rng = XorShift(0xA11CE);
    let mut runs: Vec<(u64, u64)> = (0..1000)
        .map(|_| (rng.below(len - 64), 1 + rng.below(64)))
        .collect();
    runs.sort_unstable();
    generate(&l, len, 1, &|_, _| {});
    generate(&c, len, 1, &|_, _| {});
    generate(&r, len, 1, &|at, piece| {
        let end = at + piece.len() as u64;
        for &(start, n) in &runs {
            for p in start..start + n {
                if (at..end).contains(&p) {
                    piece[(p - at) as usize] ^= 0x5A;
                }
            }
        }
    });
    (l, r, c)
}

/// `base` with `edits` (sorted by position, non-overlapping) applied in one pass.
fn apply(base: &[u8], edits: &[Edit], seed: u64) -> Vec<u8> {
    let mut rng = XorShift(seed);
    let mut out = Vec::with_capacity(base.len() + edits.len() * 4096);
    let mut at = 0usize;
    for &e in edits {
        let (pos, len) = match e {
            Edit::Insert { at, len } | Edit::Delete { at, len } | Edit::Replace { at, len } => {
                (at, len)
            }
        };
        if pos < at {
            continue;
        }
        out.extend_from_slice(&base[at..pos]);
        at = pos;
        match e {
            Edit::Insert { .. } => out.extend_from_slice(&rng.bytes(len)),
            Edit::Delete { .. } => at = (pos + len).min(base.len()),
            Edit::Replace { .. } => {
                let end = (pos + len).min(base.len());
                out.extend(base[pos..end].iter().map(|b| !b));
                at = end;
            }
        }
    }
    out.extend_from_slice(&base[at..]);
    out
}

/// A pair of `len` bytes with 1,000 seeded edits of 1–4,096 bytes.
fn edited_pair(len: u64, name: &str) -> (PathBuf, PathBuf) {
    let dir = gate_dir();
    let (l, r) = (
        dir.join(format!("{name}-left")),
        dir.join(format!("{name}-right")),
    );
    if !(l.exists() && r.exists()) {
        let base = XorShift(7).bytes(len as usize);
        let mut edits = common::random_edits(len as usize, 1000, 4096, 11);
        edits.reverse(); // ascending
        let edited = apply(&base, &edits, 13);
        std::fs::write(&l, &base).unwrap();
        std::fs::write(&r, &edited).unwrap();
    }
    (l, r)
}

fn open(path: &Path) -> HexDocument {
    HexDocument::open(
        &LocalVfs::default(),
        &lspec(path),
        &HexLoadOptions::default(),
        &Ctl::detached(),
    )
    .unwrap()
}

fn load() -> String {
    std::fs::read_to_string("/proc/loadavg")
        .unwrap_or_default()
        .trim()
        .to_owned()
}

#[test]
#[ignore = "gate G10 (by hand, release)"]
fn g10_first_screen_scan_find_memory() {
    let (l, r, c) = big_pair();
    // First screen: open, the provisional view, 64 rows.
    let base = LIVE.load(Ordering::Relaxed);
    let t = Instant::now();
    let (dl, dr) = (open(&l), open(&r));
    let view = HexView::provisional(&dl, &dr, HexLayout::default());
    let rows = view.rows(0, 64).unwrap();
    let first = t.elapsed();
    assert_eq!(rows.len(), 64);
    println!("G10 first screen (warm): {first:?}; load {}", load());
    assert!(first < Duration::from_secs(1));
    // The scan, against compare_sources of two identical files.
    let vfs = LocalVfs::default();
    let src = |p: &Path| {
        let spec = lspec(p);
        let entry = vfs.stat(&spec, FollowLinks::Yes).unwrap();
        VfsSource::new(&vfs, spec, entry)
    };
    let t = Instant::now();
    assert!(
        compare_sources(&src(&l), &src(&c), &stream(), &Ctl::detached())
            .unwrap()
            .is_same()
    );
    let compare = t.elapsed();
    let opts = HexAlignOptions {
        stream: stream(),
        ..HexAlignOptions::with_mode(AlignMode::None)
    };
    PEAK.store(LIVE.load(Ordering::Relaxed), Ordering::Relaxed);
    let t = Instant::now();
    let al = align(&dl, &dr, &opts, &Ctl::detached()).unwrap();
    let scan = t.elapsed();
    let peak = PEAK.load(Ordering::Relaxed) - base;
    let held = LIVE.load(Ordering::Relaxed) - base;
    println!(
        "G10 scan: {scan:?} vs compare_sources {compare:?} = {:.2}x; {} sections, {} differing bytes; load {}",
        scan.as_secs_f64() / compare.as_secs_f64(),
        al.stats.sections,
        al.stats.differing_bytes,
        load()
    );
    println!("G10 memory: documents + model {held} bytes held, peak {peak} bytes");
    assert!(scan.as_secs_f64() <= 1.25 * compare.as_secs_f64());
    assert!(peak as u64 <= 2 * 16 * MIB + 64 * MIB);
    // Find of an 8-byte pattern over the 4 GiB left file.
    let finder = HexFinder::new(&HexPattern::Bytes {
        bytes: b"\x01\x23\x45\x67\x89\xAB\xCD\xEF"
            .iter()
            .map(|&b| Some(b))
            .collect(),
    })
    .unwrap();
    let t = Instant::now();
    let (hits, _) = finder.all(&dl, 1000, &stream(), &Ctl::detached()).unwrap();
    let find = t.elapsed();
    let per_byte_find = find.as_secs_f64() / (4.0 * GIB as f64);
    let per_byte_scan = scan.as_secs_f64() / (8.0 * GIB as f64);
    println!(
        "G10 find: {find:?} ({} hits) = {:.2}x the scan per byte read; load {}",
        hits.len(),
        per_byte_find / per_byte_scan,
        load()
    );
    assert!(per_byte_find <= 1.5 * per_byte_scan);
    // Cancel rows: the None scan and find, cancelled after 300 ms.
    let none = cancel_after(Duration::from_millis(300), |ctl| {
        align(&dl, &dr, &opts, ctl).map(|_| ())
    });
    let found = cancel_after(Duration::from_millis(300), |ctl| {
        finder.all(&dl, 1000, &stream(), ctl).map(|_| ())
    });
    println!("G10 cancel: None scan {none:?}, find {found:?}");
    assert!(none <= Duration::from_millis(100) && found <= Duration::from_millis(100));
}

/// Runs `op`, cancels it after `delay` from another thread, and returns the time from the cancel to its return.
fn cancel_after(
    delay: Duration,
    op: impl FnOnce(&Ctl<'_>) -> Result<(), hikasa_hex::HexError>,
) -> Duration {
    let token = CancelToken::new();
    let ctl = Ctl {
        cancel: &token,
        progress: &hikasa_core::NullProgress,
    };
    std::thread::scope(|s| {
        let canceller = s.spawn(|| {
            std::thread::sleep(delay);
            token.cancel();
            Instant::now()
        });
        let result = op(&ctl);
        let done = Instant::now();
        let cancelled_at = canceller.join().unwrap();
        assert!(
            matches!(&result, Err(e) if e.is_cancelled()),
            "the operation ended before the cancel"
        );
        done.saturating_duration_since(cancelled_at)
    })
}

#[test]
#[ignore = "gate G10 (by hand, release)"]
fn g10_fast_rows_complete() {
    let (l, r) = edited_pair(GIB, "1g");
    let (dl, dr) = (open(&l), open(&r));
    let opts = HexAlignOptions {
        stream: stream(),
        ..HexAlignOptions::with_mode(AlignMode::Fast)
    };
    let base = LIVE.load(Ordering::Relaxed);
    PEAK.store(base, Ordering::Relaxed);
    let t = Instant::now();
    let al = align(&dl, &dr, &opts, &Ctl::detached()).unwrap();
    let fast = t.elapsed();
    let peak = PEAK.load(Ordering::Relaxed) - base;
    println!(
        "G10 fast: {fast:?}, peak live heap {} MiB; {} segments, {} sections, stats {:?}; load {}",
        peak as u64 / MIB,
        al.segments.len(),
        al.stats.sections,
        al.stats,
        load()
    );
    assert!(fast < Duration::from_secs(5));
    assert!(peak as u64 <= 96 * MIB);
    // Rows at 1,000 random places, warm.
    let view = HexView::new(&dl, &dr, &al, HexLayout::default());
    let mut rng = XorShift(5);
    let n = view.row_count();
    for _ in 0..1000 {
        view.rows(rng.below(n), 64).unwrap();
    }
    let mut times: Vec<Duration> = (0..1000)
        .map(|_| {
            let first = rng.below(n);
            let t = Instant::now();
            view.rows(first, 64).unwrap();
            t.elapsed()
        })
        .collect();
    times.sort_unstable();
    let p99 = times[989];
    println!(
        "G10 rows: p50 {:?}, p99 {p99:?}, max {:?}",
        times[500], times[999]
    );
    assert!(p99 < Duration::from_millis(2));
    let cancel = cancel_after(Duration::from_millis(300), |ctl| {
        align(&dl, &dr, &opts, ctl).map(|_| ())
    });
    println!("G10 cancel: Fast {cancel:?}");
    assert!(cancel <= Duration::from_millis(100));
    drop(view);
    drop(al);

    // Complete on 256 MiB.
    let (l, r) = edited_pair(256 * MIB, "256m");
    let (dl, dr) = (open(&l), open(&r));
    let opts = HexAlignOptions {
        stream: stream(),
        ..HexAlignOptions::with_mode(AlignMode::Complete)
    };
    let t = Instant::now();
    let al = align(&dl, &dr, &opts, &Ctl::detached()).unwrap();
    let complete = t.elapsed();
    println!(
        "G10 complete: {complete:?}, degraded {}, {} segments, stats {:?}; load {}",
        al.degraded,
        al.segments.len(),
        al.stats,
        load()
    );
    assert!(complete < Duration::from_secs(10) && !al.degraded);
    let cancel = cancel_after(Duration::from_millis(300), |ctl| {
        align(&dl, &dr, &opts, ctl).map(|_| ())
    });
    println!("G10 cancel: Complete {cancel:?}");
    assert!(cancel <= Duration::from_millis(100));
}
